import{U as e,gt as t,nt as n,rt as r}from"./chunks/framework.B3obAz7o.js";var i=JSON.parse(`{"title":"迈向 1.0","description":"","frontmatter":{},"headers":[],"relativePath":"zh/roadmap.md","filePath":"zh/roadmap.md","lastUpdated":1785247907000}`),a={name:`zh/roadmap.md`};function o(e,i,a,o,s,c){return t(),n(`div`,null,[...i[0]||=[r(`<h1 id="迈向-1-0" tabindex="-1">迈向 1.0 <a class="header-anchor" href="#迈向-1-0" aria-label="Permalink to “迈向 1.0”">​</a></h1><p>fontmin-rs <code>0.1.0</code> 已作为首个稳定版本发布，覆盖 CLI、Node.js 包、浏览器 WASM 包、native binding 和 8 个平台包。后续里程碑会在保持公开契约的前提下加深内部 实现，并在独立验证后最终确定 <code>1.0.0</code> 契约。</p><p>路线图采用退出条件，不承诺日历日期。只有相关检查能在 <code>main</code> 重复通过、打包后的 消费者 smoke test 覆盖受影响公开路径，并且发布流程仍可复现时，里程碑才算完成。</p><h2 id="稳定基线" tabindex="-1">稳定基线 <a class="header-anchor" href="#稳定基线" aria-label="Permalink to “稳定基线”">​</a></h2><ul><li>发布门禁会核对 11 个 npm 包、Cargo metadata、运行时内嵌版本、Changelog 和 release tag 是否使用同一版本。</li><li>CI 覆盖格式化、Rust/TypeScript 零警告 lint、Node.js 22/24/26、WASM、浏览器 加载、文档、native package smoke test、发布准备检查和 benchmark。</li><li>发布前会拒绝 high/critical 依赖安全问题，要求 Rust 行覆盖率不低于 80%，检查 npm tarball 内容，并运行消费者 smoke test。</li><li>Native 与 WASM 共享语义一致性 corpus，覆盖内置 transforms、presets、输出 metadata 和 malformed diagnostics。</li><li>有时间上限的 AddressSanitizer cargo-fuzz 会在相关改动和每周任务中运行； 最小化后的 crash 会成为永久 malformed fixture。</li><li>Rust <code>1.88.0</code> 是独立测试的 MSRV；开发与发布自动化使用仓库声明的固定 toolchain。</li></ul><h2 id="_0-1-1——契约修正" tabindex="-1">0.1.1——契约修正 <a class="header-anchor" href="#_0-1-1——契约修正" aria-label="Permalink to “0.1.1——契约修正”">​</a></h2><p>首个补丁版本修复 <code>0.1.0</code> 发布后立即发现的漂移，不扩张公开 API。</p><ul><li>将 README、安装指南、导航标签和机器可读清单统一为稳定版状态。</li><li>让 npm 包内 CLI 接受所有已冻结的 Rust CLI 参数，并用同一份契约验证两个 executable。</li><li>将 Rust、Node.js 与浏览器 pipeline 的 SVG icon-font 默认 stem 统一为 <code>iconfont</code>。</li><li>增加语义检查，防止稳定 package version 再发布预发布安装指引。</li></ul><p>退出条件：完整发布门禁通过，npm tarball CLI 与 Rust CLI 均符合公开清单，并将 <code>0.1.1</code> 发布到 <code>latest</code>。</p><h2 id="_0-2——收敛流水线边界" tabindex="-1">0.2——收敛流水线边界 <a class="header-anchor" href="#_0-2——收敛流水线边界" aria-label="Permalink to “0.2——收敛流水线边界”">​</a></h2><p><code>0.2</code> 发布线在保留稳定公开入口的同时，减少重复策略。</p><ul><li>将 npm executable 变为共享命令解析与 pipeline 行为之上的薄适配层，不再维护 第二套独立 CLI。</li><li>在 <code>fontmin_config</code> 中把内置 plugin 配置规范化为类型化领域值，移除 <code>fontmin_pipeline</code> 中重复的 JSON option decoding。</li><li>将已知的 <code>AssetMeta.custom</code> key 替换为类型化 metadata，同时保留第三方 plugin 使用的扩展 map。</li><li>按 pipeline execution、transform rules、filesystem/cache ownership 拆分 Node optimizer，同时保留现有 <code>optimize()</code> facade。</li><li>按公开 command 或 API seam 拆分过大的 CLI 与 Node integration tests。</li><li>明确 Rust workspace crates 是仅内部使用还是独立发布，并让 Cargo manifests 强制执行该决策。</li><li>将 <code>0.1.0</code> 前的设计提案明确标记为历史资料；当前架构和契约文档是事实来源。</li></ul><p>退出条件：所有公开入口保持契约，重复的 CLI 与配置规则只有一处事实来源，完整 conformance 和 package gates 在没有兼容性例外的情况下通过。</p><h2 id="_0-3——真实场景韧性与性能" tabindex="-1">0.3——真实场景韧性与性能 <a class="header-anchor" href="#_0-3——真实场景韧性与性能" aria-label="Permalink to “0.3——真实场景韧性与性能”">​</a></h2><p><code>0.3</code> 发布线通过生产规模输入积累证据，并降低剩余运行风险。</p><ul><li>扩展大体积 CJK、variable font、color font、malformed tables 和混合 delivery slices 的一致性 fixtures。</li><li>为 native 与 WASM 增加有上限的内存和耗时预算，回退报告能够定位具体阶段。</li><li>从真实故障扩充 fuzz corpus，并覆盖 parser、converter、配置加载和输出命名。</li><li>审计重复压缩/错误处理依赖、vendored patches、binary size 与上游替代路径。</li><li>验证缓存并发、取消和多进程构建中断后的清理行为。</li></ul><p>退出条件：代表性大字体保持在文档化性能预算内，每条支持的格式路径都有回归 fixture， 且已知 vendored/dependency 风险都有负责人和替代决策。</p><h2 id="_1-0——独立验证的公开契约" tabindex="-1">1.0——独立验证的公开契约 <a class="header-anchor" href="#_1-0——独立验证的公开契约" aria-label="Permalink to “1.0——独立验证的公开契约”">​</a></h2><p><code>1.0.0</code> 不是对 <code>0.1</code> 契约的简单改名。它会在真实项目证据形成最终边界后，启动独立 RC 周期。</p><ul><li>收集 CLI、Node.js 和浏览器消费者的兼容性报告。</li><li>为每项有意的契约变化发布迁移说明。</li><li>完成已公告的弃用周期，仅移除符合弃用策略的 API。</li><li>重新确认 runtime、native targets、浏览器能力、Rust MSRV、diagnostics 与生成 文件命名规则。</li><li>至少通过一个 RC 周期，且不存在未解决的 P0/P1 正确性、安全、性能或打包问题。</li></ul><p>退出条件：独立版本的 RC 契约通过完整发布门禁和真实项目验证，同一提交无需发布时修补 即可提升为 <code>1.0.0</code>。</p>`,21)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};